/**
 * Какие файлы принимает портал
 *
 * Список поддерживаемых расширений и того, что портал с ними сделает.
 *
 * Интерфейс берёт подписи отсюда, а не хранит свою копию: иначе при подключении нового
 * обработчика обещания на экране разойдутся с поведением сервера.
 */
export const readUploadCapabilities = <ThrowOnError extends boolean = false>(options: Options<ReadUploadCapabilitiesData, ThrowOnError>): RequestResult<ReadUploadCapabilitiesResponses, ReadUploadCapabilitiesErrors, ThrowOnError> => (options.client ?? client).get<ReadUploadCapabilitiesResponses, ReadUploadCapabilitiesErrors, ThrowOnError>({ url: '/api/v1/projects/{project_id}/upload-capabilities', ...options });

/**
 * Загрузить файл в проект
 *
 * Принимает файл, кладёт его в хранилище и заводит документ с ревизией.
 *
 * Распознавание здесь не выполняется: для ZIP-пакета создаётся задание импорта в состоянии
 * «в очереди», для остальных типов ревизия сохраняется с честным статусом обработки.
 */
export const uploadFile = <ThrowOnError extends boolean = false>(options: Options<UploadFileData, ThrowOnError>): RequestResult<UploadFileResponses, UploadFileErrors, ThrowOnError> => (options.client ?? client).post<UploadFileResponses, UploadFileErrors, ThrowOnError>({
    ...formDataBodySerializer,
    url: '/api/v1/projects/{project_id}/uploads',
    ...options,
    headers: {
        'Content-Type': null,
        ...options.headers
    }
});

/**
 * Ревизия документа
 */
export const readRevision = <ThrowOnError extends boolean = false>(options: Options<ReadRevisionData, ThrowOnError>): RequestResult<ReadRevisionResponses, ReadRevisionErrors, ThrowOnError> => (options.client ?? client).get<ReadRevisionResponses, ReadRevisionErrors, ThrowOnError>({ url: '/api/v1/revisions/{revision_id}', ...options });

/**
 * Артефакты распознавания
 */
