/**
 * Калибровка
 */
export const readCalibration = <ThrowOnError extends boolean = false>(options: Options<ReadCalibrationData, ThrowOnError>): RequestResult<ReadCalibrationResponses, ReadCalibrationErrors, ThrowOnError> => (options.client ?? client).get<ReadCalibrationResponses, ReadCalibrationErrors, ThrowOnError>({ url: '/api/v1/scale-calibrations/{calibration_id}', ...options });

/**
 * Сделать масштаб действующим
 *
 * Назначает калибровку действующей для листа.
 *
 * Уже посчитанные измерения не меняются: каждое хранит явную ссылку на свою калибровку.
 * Перепривязка — отдельное действие, а не побочный эффект этого нажатия (ADR-0018).
 */
export const makeCalibrationDefault = <ThrowOnError extends boolean = false>(options: Options<MakeCalibrationDefaultData, ThrowOnError>): RequestResult<MakeCalibrationDefaultResponses, MakeCalibrationDefaultErrors, ThrowOnError> => (options.client ?? client).post<MakeCalibrationDefaultResponses, MakeCalibrationDefaultErrors, ThrowOnError>({ url: '/api/v1/scale-calibrations/{calibration_id}/default', ...options });

/**
 * Подтвердить масштаб
 *
 * Подтверждает калибровку или снимает подтверждение.
 *
 * Отдельное право `takeoff.verify`: подтверждение — это ответственность за число перед
 * заказчиком, и она не обязана совпадать с правом это число внести.
 */
export const setCalibrationVerification = <ThrowOnError extends boolean = false>(options: Options<SetCalibrationVerificationData, ThrowOnError>): RequestResult<SetCalibrationVerificationResponses, SetCalibrationVerificationErrors, ThrowOnError> => (options.client ?? client).post<SetCalibrationVerificationResponses, SetCalibrationVerificationErrors, ThrowOnError>({
    url: '/api/v1/scale-calibrations/{calibration_id}/verification',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Каноническая геометрия листа
 *
 * Размер страницы в точках PDF — единственное основание для физических величин.
 *
 * Отдельный ресурс, а не поле листа: список на 77 листов не должен тащить геометрию
 * каждого, а причина её отсутствия у геометрии своя (ADR-0016).
 */
export const readSheetGeometry = <ThrowOnError extends boolean = false>(options: Options<ReadSheetGeometryData, ThrowOnError>): RequestResult<ReadSheetGeometryResponses, ReadSheetGeometryErrors, ThrowOnError> => (options.client ?? client).get<ReadSheetGeometryResponses, ReadSheetGeometryErrors, ThrowOnError>({ url: '/api/v1/sheets/{sheet_id}/geometry', ...options });

/**
 * Измерения листа
 *
 * Активные измерения одного листа.
 *
 * Именно листа, а не документа: просмотрщик показывает открытую страницу, и тянуть
 * измерения всех 77 листов ради одного — это тот же N+1, только наоборот.
 */
export const listSheetMeasurements = <ThrowOnError extends boolean = false>(options: Options<ListSheetMeasurementsData, ThrowOnError>): RequestResult<ListSheetMeasurementsResponses, ListSheetMeasurementsErrors, ThrowOnError> => (options.client ?? client).get<ListSheetMeasurementsResponses, ListSheetMeasurementsErrors, ThrowOnError>({ url: '/api/v1/sheets/{sheet_id}/measurements', ...options });

/**
 * Создать измерение
 */
export const createMeasurement = <ThrowOnError extends boolean = false>(options: Options<CreateMeasurementData, ThrowOnError>): RequestResult<CreateMeasurementResponses, CreateMeasurementErrors, ThrowOnError> => (options.client ?? client).post<CreateMeasurementResponses, CreateMeasurementErrors, ThrowOnError>({
    url: '/api/v1/sheets/{sheet_id}/measurements',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Создать несколько измерений
 *
 * Пакетная постановка. Нужна счёту: метки ставят подряд, а не по одной с ожиданием.
 *
 * Пакет атомарен: одна негодная геометрия отменяет весь. Частичный результат заставил бы
 * клиента выяснять, какие из двадцати меток сохранились, — а он их уже нарисовал.
 */
export const createMeasurementsBatch = <ThrowOnError extends boolean = false>(options: Options<CreateMeasurementsBatchData, ThrowOnError>): RequestResult<CreateMeasurementsBatchResponses, CreateMeasurementsBatchErrors, ThrowOnError> => (options.client ?? client).post<CreateMeasurementsBatchResponses, CreateMeasurementsBatchErrors, ThrowOnError>({
    url: '/api/v1/sheets/{sheet_id}/measurements/batch',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Величины листа
 *
 * Величины всех измерений открытого листа и итоги по строкам обмера.
 *
 * Один запрос на лист, а не на измерение: просмотрщик показывает страницу целиком, и
 * сотня обращений ради сотни меток была бы тем же N+1, только со стороны клиента.
 *
 * Область — лист и его ревизия, и это указано в ответе. Итог по документу складывал бы
 * измерения разных ревизий и посчитал бы одни и те же двери дважды (ADR-0019).
 *
 * Величина без масштаба возвращается состоянием `unavailable_no_scale`, а не нулём: ноль
 * — это утверждение о величине, и ложное.
 */
export const readSheetQuantities = <ThrowOnError extends boolean = false>(options: Options<ReadSheetQuantitiesData, ThrowOnError>): RequestResult<ReadSheetQuantitiesResponses, ReadSheetQuantitiesErrors, ThrowOnError> => (options.client ?? client).get<ReadSheetQuantitiesResponses, ReadSheetQuantitiesErrors, ThrowOnError>({ url: '/api/v1/sheets/{sheet_id}/quantities', ...options });

/**
 * Области на листе
 */
export const listSheetRegions = <ThrowOnError extends boolean = false>(options: Options<ListSheetRegionsData, ThrowOnError>): RequestResult<ListSheetRegionsResponses, ListSheetRegionsErrors, ThrowOnError> => (options.client ?? client).get<ListSheetRegionsResponses, ListSheetRegionsErrors, ThrowOnError>({ url: '/api/v1/sheets/{sheet_id}/regions', ...options });

/**
 * Калибровки масштаба листа
 *
 * Все калибровки листа, новые сверху.
 *
 * Не страница: калибровок на листе единицы, а не сотни. Пагинация здесь была бы
 * механикой без причины.
 */
export const listSheetCalibrations = <ThrowOnError extends boolean = false>(options: Options<ListSheetCalibrationsData, ThrowOnError>): RequestResult<ListSheetCalibrationsResponses, ListSheetCalibrationsErrors, ThrowOnError> => (options.client ?? client).get<ListSheetCalibrationsResponses, ListSheetCalibrationsErrors, ThrowOnError>({ url: '/api/v1/sheets/{sheet_id}/scale-calibrations', ...options });

/**
 * Задать масштаб по известному размеру
 *
 * Создаёт калибровку из двух точек и подписанного на чертеже размера.
 *
 * Коэффициент считает сервер. Клиент присылает точки и размер — не множитель.
 */
export const createSheetCalibration = <ThrowOnError extends boolean = false>(options: Options<CreateSheetCalibrationData, ThrowOnError>): RequestResult<CreateSheetCalibrationResponses, CreateSheetCalibrationErrors, ThrowOnError> => (options.client ?? client).post<CreateSheetCalibrationResponses, CreateSheetCalibrationErrors, ThrowOnError>({
    url: '/api/v1/sheets/{sheet_id}/scale-calibrations',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Изменить строку обмера
 *
 * Меняет описание строки.
 *
 * Типа геометрии в запросе нет: сменить его у строки с измерениями значило бы объявить
 * посчитанные точки площадями.
 */
export const updateTakeoffItem = <ThrowOnError extends boolean = false>(options: Options<UpdateTakeoffItemData, ThrowOnError>): RequestResult<UpdateTakeoffItemResponses, UpdateTakeoffItemErrors, ThrowOnError> => (options.client ?? client).patch<UpdateTakeoffItemResponses, UpdateTakeoffItemErrors, ThrowOnError>({
    url: '/api/v1/takeoff-items/{item_id}',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Архивировать строку обмера
 *
 * Архивирует строку.
 *
 * Удаления нет: строка, по которой посчитаны объёмы, — это документ, и удалить её значит
 * потерять объяснение чисел, которые могли уйти заказчику.
 */
export const archiveTakeoffItem = <ThrowOnError extends boolean = false>(options: Options<ArchiveTakeoffItemData, ThrowOnError>): RequestResult<ArchiveTakeoffItemResponses, ArchiveTakeoffItemErrors, ThrowOnError> => (options.client ?? client).post<ArchiveTakeoffItemResponses, ArchiveTakeoffItemErrors, ThrowOnError>({ url: '/api/v1/takeoff-items/{item_id}/archive', ...options });

/**
 * Liveness probe
 */
export const liveness = <ThrowOnError extends boolean = false>(options?: Options<LivenessData, ThrowOnError>): RequestResult<LivenessResponses, unknown, ThrowOnError> => (options?.client ?? client).get<LivenessResponses, unknown, ThrowOnError>({ url: '/health/live', ...options });

/**
 * Readiness probe
 *
 * Готовность API отвечать на запросы.
 *
 * Ключевое различие — между обязательными компонентами и необязательными. Без базы,
 * схемы и хранилища API не может ответить почти ни на что: это 503, и балансировщик
 * обязан увести с него трафик.
 *
 * Исполнитель заданий — другое дело. Когда он лежит, портал по-прежнему показывает
 * проекты, документы и чертежи; не работает только запуск новых импортов. Отдавать
 * 503 в этом случае значит увести трафик с полностью исправного API и превратить
 * частичную поломку в полную (ADR-0015).
 */
export const readiness = <ThrowOnError extends boolean = false>(options?: Options<ReadinessData, ThrowOnError>): RequestResult<ReadinessResponses, unknown, ThrowOnError> => (options?.client ?? client).get<ReadinessResponses, unknown, ThrowOnError>({ url: '/health/ready', ...options });
